CREATE VIEW [dbo].[ApparecchiNuoviInMagazzino] AS  SELECT 'NSL' AS Categoria ,'New Slot' AS Tipo, NULL AS IdLocale,2 AS TipoOggetto,'NSL' AS TipoOggettoDesc,IdDedicato AS CodiceOggetto,prop AS Proprieta,agente AS Associato, matricola, nome as Modello, identificativo, nullaosta, 1 AS TM, NULL AS idmove, NULL AS IdStorico, 0 as IdPadre, DataCreazione AS DataDa, NULL AS DataA, DataCreazione, fornitore, costruttore, IdMagazzino, 0 AS Ordinamento, 0 AS OrdinamentoCategoria FROM dedicati WHERE DataFine IS NULL AND partipologiamonopoli=1 AND iddedicato NOT IN (SELECT dedicato FROM move WHERE move.dedicato=dedicati.iddedicato) AND iddedicato NOT IN (SELECT codiceoggetto FROM storico WHERE storico.codiceoggetto=dedicati.iddedicato AND storico.tipo=2) UNION SELECT 'C7A' AS Categoria ,'Gioco' AS Tipo, NULL AS IdLocale,2 AS TipoOggetto,'GIO' AS TipoOggettoDesc,IdDedicato AS CodiceOggetto,prop AS Proprieta,agente AS Associato, matricola,nome as Modello, identificativo,nullaosta, ParTipologiaMonopoli AS TM, NULL AS idmove,NULL AS IdStorico, 0 as IdPadre, DataCreazione AS DataDa, NULL AS DataA,  DataCreazione, fornitore, costruttore, IdMagazzino, 1 AS Ordinamento, 1 AS OrdinamentoCategoria FROM dedicati WHERE DataFine IS NULL AND partipologiamonopoli=2  AND iddedicato NOT IN (SELECT dedicato FROM move WHERE move.dedicato=dedicati.iddedicato) AND iddedicato NOT IN (SELECT codiceoggetto FROM storico WHERE storico.codiceoggetto=dedicati.iddedicato AND storico.tipo=2) UNION SELECT 'C7C' AS Categoria ,'Gioco' AS Tipo, NULL AS IdLocale,2 AS TipoOggetto,'GIO' AS TipoOggettoDesc,iddedicato AS CodiceOggetto,prop AS Proprieta,agente AS Associato, matricola,nome as Modello, identificativo,nullaosta, ParTipologiaMonopoli AS TM, NULL AS idmove,NULL AS IdStorico, 0 as IdPadre, datacreazione AS DataDa, NULL AS DataA, DataCreazione, fornitore, costruttore, IdMagazzino, 1 AS Ordinamento, 2 AS OrdinamentoCategoria FROM dedicati WHERE DataFine IS NULL AND partipologiamonopoli=4  AND iddedicato NOT IN (SELECT dedicato FROM move WHERE move.dedicato=dedicati.iddedicato) AND iddedicato NOT IN (SELECT codiceoggetto FROM storico WHERE storico.codiceoggetto=dedicati.iddedicato AND storico.tipo=2) UNION SELECT 'MEC' AS Categoria ,'Gioco' AS Tipo, NULL AS IdLocale,2 AS TipoOggetto,'GIO' AS TipoOggettoDesc,iddedicato AS CodiceOggetto,prop AS Proprieta,agente AS Associato, matricola,nome as Modello, identificativo,nullaosta, ParTipologiaMonopoli AS TM, NULL AS idmove,NULL AS IdStorico, 0 as IdPadre, DataCreazione AS DataDa, NULL AS DataA, DataCreazione, fornitore, costruttore, IdMagazzino, 1 AS Ordinamento, 3 AS OrdinamentoCategoria FROM dedicati WHERE DataFine IS NULL AND  (partipologiamonopoli>4 OR partipologiamonopoli IS NULL)  AND iddedicato NOT IN (SELECT dedicato FROM move WHERE move.dedicato=dedicati.iddedicato) AND iddedicato NOT IN (SELECT codiceoggetto FROM storico WHERE storico.codiceoggetto=dedicati.iddedicato AND storico.tipo=2) UNION SELECT 'NSL' AS Categoria, 'Mobile' AS Tipo, NULL AS IdLocale,0 AS TipoOggetto,'MOB' AS TipoOggettoDesc,idmobile AS CodiceOggetto,prop AS Proprieta,agente AS Associato, matricola,modello, identificativo,nullaosta, ParTipologiaMonopoli AS TM, NULL AS idmove,NULL AS IdStorico, 0 as IdPadre, datacreazione AS DataDa, NULL AS DataA, DataCreazione, fornitore, costruttore, IdMagazzino, 2 AS Ordinamento, 0 AS OrdinamentoCategoria FROM mobili WHERE DataFine IS NULL AND ParTipologiaMonopoli=1  AND idmobile NOT IN (SELECT mobile FROM move WHERE move.mobile=mobili.idmobile) AND idmobile NOT IN (SELECT codiceoggetto FROM storico WHERE storico.codiceoggetto=mobili.idmobile AND storico.tipo=0) UNION SELECT 'C7A' AS Categoria, 'Mobile' AS Tipo, NULL AS IdLocale,0 AS TipoOggetto,'MOB' AS TipoOggettoDesc,idmobile AS CodiceOggetto,prop AS Proprieta,agente AS Associato, matricola,modello, identificativo,nullaosta, ParTipologiaMonopoli AS TM, NULL AS idmove,NULL AS IdStorico, 0 as IdPadre, datacreazione AS DataDa, NULL AS DataA, DataCreazione, fornitore, costruttore, IdMagazzino, 2 AS Ordinamento, 1 AS OrdinamentoCategoria FROM mobili WHERE DataFine IS NULL AND ParTipologiaMonopoli=2  AND idmobile NOT IN (SELECT mobile FROM move WHERE move.mobile=mobili.idmobile) AND idmobile NOT IN (SELECT codiceoggetto FROM storico WHERE storico.codiceoggetto=mobili.idmobile AND storico.tipo=0) UNION SELECT 'C7C' AS Categoria, 'Mobile' AS Tipo, NULL AS IdLocale,0 AS TipoOggetto,'MOB' AS TipoOggettoDesc,idmobile AS CodiceOggetto,prop AS Proprieta,agente AS Associato, matricola,modello, identificativo,nullaosta, ParTipologiaMonopoli AS TM, NULL AS idmove,NULL AS IdStorico, 0 as IdPadre, datacreazione AS DataDa, NULL AS DataA, DataCreazione, fornitore, costruttore, IdMagazzino, 2 AS Ordinamento, 2 AS OrdinamentoCategoria FROM mobili WHERE DataFine IS NULL AND ParTipologiaMonopoli=4  AND idmobile NOT IN (SELECT mobile FROM move WHERE move.mobile=mobili.idmobile) AND idmobile NOT IN (SELECT codiceoggetto FROM storico WHERE storico.codiceoggetto=mobili.idmobile AND storico.tipo=0) UNION SELECT 'MEC' AS Categoria, 'Mobile' AS Tipo, NULL AS IdLocale,0 AS TipoOggetto,'MOB' AS TipoOggettoDesc,idmobile AS CodiceOggetto,prop AS Proprieta,agente AS Associato, matricola,modello, identificativo,nullaosta, ParTipologiaMonopoli AS TM, NULL AS idmove,NULL AS IdStorico, 0 as IdPadre, datacreazione AS DataDa, NULL AS DataA, DataCreazione, fornitore, costruttore, IdMagazzino, 2 AS Ordinamento, 3 AS OrdinamentoCategoria FROM mobili WHERE DataFine IS NULL AND (partipologiamonopoli>4 OR partipologiamonopoli IS NULL)  AND idmobile NOT IN (SELECT mobile FROM move WHERE move.mobile=mobili.idmobile) AND idmobile NOT IN (SELECT codiceoggetto FROM storico WHERE storico.codiceoggetto=mobili.idmobile AND storico.tipo=0) UNION SELECT 'SCH' AS Categoria, 'Scheda' AS Tipo, NULL AS IdLocale,1 AS TipoOggetto,'SCH' AS TipoOggettoDesc, idscheda AS CodiceOggetto,prop AS Proprieta,agente AS Associato, matricola,nome as Modello, '' AS identificativo,'' AS nullaosta, NULL AS TM ,NULL AS idmove,NULL AS IdStorico, NULL as IdPadre, datacreazione AS DataDa, NULL AS DataA, DataCreazione, fornitore, costruttore, IdMagazzino, 3 AS Ordinamento, 4 AS OrdinamentoCategoria FROM schede WHERE DataFine IS NULL AND idscheda NOT IN (SELECT scheda FROM move WHERE move.scheda=schede.idscheda) AND idscheda NOT IN (SELECT codiceoggetto FROM storico WHERE storico.codiceoggetto=schede.idscheda AND storico.tipo=1) UNION SELECT 'DIS' AS Categoria, 'Distributore' AS Tipo, NULL AS IdLocale,15 AS TipoOggetto,'DIS' AS TipoOggettoDesc, iddistributore AS CodiceOggetto,prop AS Proprieta,agente AS Associato, matricola,nome as Modello, '' AS identificativo,'' AS nullaosta,  NULL AS TM,NULL AS idmove,NULL AS IdStorico, 0 as IdPadre, datacreazione AS DataDa, NULL AS DataA, DataCreazione, fornitore, costruttore, IdMagazzino, 4 AS Ordinamento, 5 AS OrdinamentoCategoria FROM distribut WHERE DataFine IS NULL AND iddistributore NOT IN (SELECT distributore FROM move WHERE move.distributore=distribut.iddistributore) AND iddistributore NOT IN (SELECT codiceoggetto FROM storico WHERE storico.codiceoggetto=distribut.iddistributore AND storico.tipo=15)
GO
